import test from 'node:test';
import assert from 'node:assert/strict';
import { createInvoice, issueInvoice, invoiceTotals } from '../src/invoices.js';
import { recordPayment } from '../src/payments.js';
import { overdueInvoices } from '../src/reports.js';

test('overdueInvoices returns empty array when no invoices', () => {
  const r = overdueInvoices([], '2025-10-31');
  assert.deepEqual(r, []);
});

test('overdueInvoices excludes draft invoices', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  const invoice = r1.value;

  const r2 = overdueInvoices([invoice], '2025-10-31');
  assert.equal(r2.length, 0);
});

test('overdueInvoices includes issued invoice past due date', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
    terms: 'NET14',
  });
  const invoice = r1.value;
  const r2 = issueInvoice(invoice, []);
  const issued = r2.value;

  const r3 = overdueInvoices([issued], '2025-10-22');
  assert.equal(r3.length, 1);
  assert.equal(r3[0].number, 'INV-2025-0001');
  assert.equal(r3[0].customerId, 'C-001');
  assert.equal(r3[0].dueDate, '2025-10-21');
});

test('overdueInvoices excludes invoices not yet due', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
    terms: 'NET14',
  });
  const invoice = r1.value;
  const r2 = issueInvoice(invoice, []);
  const issued = r2.value;

  const r3 = overdueInvoices([issued], '2025-10-21');
  assert.equal(r3.length, 0);
});

test('overdueInvoices calculates daysOverdue correctly', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
    terms: 'NET14',
  });
  const invoice = r1.value;
  const r2 = issueInvoice(invoice, []);
  const issued = r2.value;

  const r3 = overdueInvoices([issued], '2025-10-30');
  assert.equal(r3[0].daysOverdue, 9);
});

test('overdueInvoices includes due amount', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
    terms: 'NET14',
  });
  const invoice = r1.value;
  const r2 = issueInvoice(invoice, []);
  const issued = r2.value;
  const totals = invoiceTotals(issued);

  const r3 = overdueInvoices([issued], '2025-10-22');
  assert.equal(r3[0].due, totals.total);
});

test('overdueInvoices calculates due after partial payment', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
    terms: 'NET14',
  });
  const invoice = r1.value;
  const r2 = issueInvoice(invoice, []);
  const issued = r2.value;
  const totals = invoiceTotals(issued);
  const half = Math.floor(totals.total / 2);

  const r3 = recordPayment(issued, { amount: half, date: '2025-10-15' });
  const partially = r3.value;

  const r4 = overdueInvoices([partially], '2025-10-22');
  assert.equal(r4[0].due, totals.total - half);
});

test('overdueInvoices excludes paid invoices', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
    terms: 'NET14',
  });
  const invoice = r1.value;
  const r2 = issueInvoice(invoice, []);
  const issued = r2.value;
  const totals = invoiceTotals(issued);

  const r3 = recordPayment(issued, { amount: totals.total, date: '2025-10-15' });
  const paid = r3.value;

  const r4 = overdueInvoices([paid], '2025-10-22');
  assert.equal(r4.length, 0);
});

test('overdueInvoices includes partially_paid invoices', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
    terms: 'NET14',
  });
  const invoice = r1.value;
  const r2 = issueInvoice(invoice, []);
  const issued = r2.value;
  const totals = invoiceTotals(issued);
  const third = Math.floor(totals.total / 3);

  const r3 = recordPayment(issued, { amount: third, date: '2025-10-15' });
  const partially = r3.value;

  const r4 = overdueInvoices([partially], '2025-10-22');
  assert.equal(r4.length, 1);
  assert.equal(r4[0].number, 'INV-2025-0001');
});

test('overdueInvoices sorts by daysOverdue most first', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
    terms: 'NET14',
  });
  const r2 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-10',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
    terms: 'NET14',
  });
  const r3 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-05',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
    terms: 'NET14',
  });

  const inv1 = issueInvoice(r1.value, []);
  const inv2 = issueInvoice(r2.value, ['INV-2025-0001']);
  const inv3 = issueInvoice(r3.value, ['INV-2025-0001', 'INV-2025-0002']);

  const r4 = overdueInvoices([inv1.value, inv2.value, inv3.value], '2025-10-31');
  assert.equal(r4.length, 3);
  assert.equal(r4[0].dueDate, '2025-10-19');
  assert.equal(r4[1].dueDate, '2025-10-21');
  assert.equal(r4[2].dueDate, '2025-10-24');
  assert.ok(r4[0].daysOverdue > r4[1].daysOverdue);
  assert.ok(r4[1].daysOverdue > r4[2].daysOverdue);
});

test('overdueInvoices with single day overdue', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
    terms: 'NET14',
  });
  const invoice = r1.value;
  const r2 = issueInvoice(invoice, []);
  const issued = r2.value;

  const r3 = overdueInvoices([issued], '2025-10-22');
  assert.equal(r3[0].daysOverdue, 1);
});

test('overdueInvoices with zero days overdue excluded', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
    terms: 'NET14',
  });
  const invoice = r1.value;
  const r2 = issueInvoice(invoice, []);
  const issued = r2.value;

  const r3 = overdueInvoices([issued], '2025-10-21');
  assert.equal(r3.length, 0);
});

test('overdueInvoices handles multiple customers', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
    terms: 'NET14',
  });
  const r2 = createInvoice({
    customerId: 'C-003',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
    terms: 'NET14',
  });

  const inv1 = issueInvoice(r1.value, []);
  const inv2 = issueInvoice(r2.value, ['INV-2025-0001']);

  const r3 = overdueInvoices([inv1.value, inv2.value], '2025-10-31');
  assert.equal(r3.length, 2);
  assert.equal(r3[0].customerId, 'C-001');
  assert.equal(r3[1].customerId, 'C-003');
});

test('overdueInvoices with EOM terms', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
    terms: 'EOM',
  });
  const invoice = r1.value;
  const r2 = issueInvoice(invoice, []);
  const issued = r2.value;

  const r3 = overdueInvoices([issued], '2025-11-01');
  assert.equal(r3.length, 1);
  assert.equal(r3[0].dueDate, '2025-10-31');
  assert.equal(r3[0].daysOverdue, 1);
});

test('overdueInvoices with large overdue amount', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-01',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
    terms: 'NET14',
  });
  const invoice = r1.value;
  const r2 = issueInvoice(invoice, []);
  const issued = r2.value;

  const r3 = overdueInvoices([issued], '2025-10-07');
  assert.ok(r3.length === 1);
  assert.ok(r3[0].daysOverdue > 250);
});

test('overdueInvoices does not include future invoices', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-11-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
    terms: 'NET14',
  });
  const invoice = r1.value;
  const r2 = issueInvoice(invoice, []);
  const issued = r2.value;

  const r3 = overdueInvoices([issued], '2025-10-31');
  assert.equal(r3.length, 0);
});

test('overdueInvoices preserves invoice number', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
    terms: 'NET14',
  });
  const invoice = r1.value;
  const r2 = issueInvoice(invoice, ['INV-2025-0042']);
  const issued = r2.value;

  const r3 = overdueInvoices([issued], '2025-10-31');
  assert.equal(r3[0].number, 'INV-2025-0043');
});

test('overdueInvoices with discount applied', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1, discountPercent: 20 }],
    terms: 'NET14',
  });
  const invoice = r1.value;
  const r2 = issueInvoice(invoice, []);
  const issued = r2.value;
  const totals = invoiceTotals(issued);

  const r3 = overdueInvoices([issued], '2025-10-31');
  assert.equal(r3.length, 1);
  assert.equal(r3[0].due, totals.total);
});

